// На странице: форма #signup-form с полями #name, #email, #age,
// списком #direction и флажком #agree. У каждого поля свой элемент ошибки:
// #name-error, #email-error, #age-error, #direction-error, #agree-error
// (id ошибки записан в атрибуте aria-describedby поля).
// Кнопка #submit-btn, сообщение об успехе - #form-message.
//
// Учебный «сервер» уже есть:
// sendApplication(data, onSuccess) - принимает данные и через 1 секунду
// вызывает функцию onSuccess (как будто сервер ответил «принято»).

// 1. Сохраните jQuery-объекты формы, полей, кнопки и сообщения в константы

// 2. function showError($field, text) - текст в элемент ошибки + aria-invalid="true"
//    function clearError($field) - пустой текст + убрать aria-invalid

// 3. function validateForm() - проверяет ВСЕ поля и возвращает true / false:
//    имя после trim() не пустое ("Введите имя") и не короче 2 ("Имя - не короче 2 символов");
//    email содержит @ ("Введите email с символом @");
//    возраст - число от 14 до 60 ("Возраст - число от 14 до 60");
//    направление выбрано ("Выберите направление");
//    флажок отмечен ("Подтвердите согласие с правилами")

// 4. $form.on("submit", ...): preventDefault, очистить #form-message, проверка;
//    при успехе - кнопку заблокировать с текстом "Отправка...",
//    sendApplication($form.serializeArray(), функция) и внутри функции:
//    сообщение "Спасибо, Анна! Вы записаны: Веб-разработка.", сброс формы,
//    кнопка снова доступна с текстом "Записаться"

task.setup:
const sentData = [];
let pendingCallbacks = [];
function sendApplication(data, onSuccess) {
    sentData.push(data);
    pendingCallbacks.push(onSuccess);
    setTimeout(finishSending, 1000);
}
function finishSending() {
    const callbacks = pendingCallbacks;
    pendingCallbacks = [];
    callbacks.forEach((callback) => callback());
}
